const LEVEL_NAMES = {} // optional per-level name/subtitle overrides

// Derive the nested level structure the app consumes, ordered by `order`.
export const levels = [...new Set(words.map((w) => w.level))]
  .sort((a, b) => a - b)
  .map((level) => {
    const cards = words
      .filter((w) => w.level === level)
      .sort((a, b) => a.order - b.order)
    return {
      id: `level-${level}`,
      level,
      name: LEVEL_NAMES[level]?.name || `Level ${level}`,
      subtitle: LEVEL_NAMES[level]?.subtitle || `${cards.length} words`,
      cards,
    }
  })

export const allCards = levels.flatMap((lvl) => lvl.cards.map((c) => ({ ...c, levelId: lvl.id })))

export const getLevel = (id) => levels.find((lvl) => lvl.id === id)

// Cumulative pool: choosing level N includes every word from levels 1..N.
export const cardsUpToLevel = (level) => words.filter((w) => w.level <= level)
